<script setup lang="ts">
import { ref } from 'vue';
import { useRouter } from 'vue-router';
import { useClub } from '../stores/club';
import { api, errorMessage } from '../services/api';
const club = useClub(), router = useRouter();
const name = ref(''), token = ref(''), error = ref(''), busy = ref(false);
async function finish() { await club.load(); await router.replace('/'); }
async function create() { busy.value = true; error.value = ''; try { await api.post('/organizations', { name: name.value.trim() }); await finish(); } catch (e) { error.value = errorMessage(e); } finally { busy.value = false; } }
async function join() { busy.value = true; error.value = ''; try { await api.post('/organizations/invitations/accept', { token: token.value.trim() }); await finish(); } catch (e) { error.value = errorMessage(e); } finally { busy.value = false; } }
async function enter(id: string) { busy.value = true; error.value = ''; try { await club.select(id); await router.replace('/'); } catch (e) { error.value = errorMessage(e); } finally { busy.value = false; } }
</script>
<template><section><div class="page-heading"><div><span class="eyebrow">TU EQUIPO EN FOOTLAB</span><h1>Un espacio para <span class="accent">tu club.</span></h1><p>Crea el espacio privado de tu equipo o únete con una invitación. Cada persona entra con su propia cuenta.</p></div></div><p v-if="error" class="alert error" role="alert">{{ error }}</p><div class="dashboard-grid"><section class="panel"><h2>Crear mi equipo</h2><p class="muted">Serás su propietario y podrás invitar a tu cuerpo técnico. Tus jugadores, partidos y análisis estarán dentro de este espacio.</p><form class="editor-form section-gap" @submit.prevent="create"><label>Nombre del equipo o club<input v-model="name" required minlength="2" maxlength="120" autocomplete="organization"></label><button class="button primary" :disabled="busy">Crear espacio privado</button></form></section><section class="panel"><h2>Unirme a un equipo</h2><p class="muted">Usa la cuenta del correo al que te invitaron. Solicita el código al administrador de tu club.</p><form class="editor-form section-gap" @submit.prevent="join"><label>Código de invitación<input v-model="token" required pattern="[a-f0-9]{64}" minlength="64" maxlength="64" autocomplete="off" spellcheck="false"></label><button class="button primary" :disabled="busy">Aceptar invitación</button></form></section></div><section v-if="club.memberships.length" class="panel section-gap"><h2>Mis equipos</h2><div v-for="m in club.memberships" :key="m.organization.id" class="roster-row"><strong>{{ m.organization.name }}</strong><span class="role-tag">{{ m.role.key }}</span><button class="button subtle" :disabled="busy" @click="enter(m.organization.id)">Entrar</button></div></section></section></template>
